<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\Interview;use App\Models\JobApplication;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class CandidateProcessController extends Controller{public function show(Request $request,JobApplication $application):JsonResponse{$this->owns($request,$application);$application->load('job.company:id,name','messages.sender:id,name,account_type','interviews');$application->messages()->where('sender_id','!=',$request->user()->id)->whereNull('read_at')->update(['read_at'=>now()]);return response()->json(['data'=>$application]);}public function message(Request $request,JobApplication $application):JsonResponse{$this->owns($request,$application);abort_if(in_array($application->status,['withdrawn','hired','rejected']),422,'El proceso está cerrado.');$data=$request->validate(['body'=>['required','string','max:5000']]);$message=$application->messages()->create(['sender_id'=>$request->user()->id,'body'=>$data['body']]);return response()->json(['data'=>$message->load('sender:id,name,account_type'),'message'=>'Mensaje enviado.'],201);}public function respond(Request $request,Interview $interview):JsonResponse{$application=$interview->application;$this->owns($request,$application);$data=$request->validate(['response'=>['required',Rule::in(['accepted','declined'])]]);abort_unless($interview->status==='scheduled',422,'Esta entrevista ya fue respondida.');$interview->update(['status'=>$data['response'],'responded_at'=>now()]);return response()->json(['data'=>$interview,'message'=>$data['response']==='accepted'?'Entrevista confirmada.':'Entrevista rechazada.']);}private function owns(Request $request,JobApplication $application):void{abort_unless($request->user()->account_type==='candidate'&&$application->user_id===$request->user()->id,404);}}
